insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('cb000000-0000-0000-0000-000000000001', 'ukmla', 'c55b867d-71cb-4953-8322-566ac515f0b1',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('cb000000-0000-0000-0000-000000000001', 'A', 'Flucloxacillin', false, 'Ruled out because flucloxacillin is a penicillin and should not be given to a patient with a history consistent with a true penicillin allergy (rash and facial swelling suggesting an IgE-mediated reaction).', 1),
('cb000000-0000-0000-0000-000000000001', 'B', 'Clarithromycin', true, 'Correct. In a patient with a genuine penicillin allergy, a macrolide such as clarithromycin (or doxycycline) provides adequate cover against the streptococcal and staphylococcal organisms that typically cause cellulitis, without cross-reacting with penicillins.', 2),
('cb000000-0000-0000-0000-000000000001', 'C', 'Co-amoxiclav', false, 'Ruled out because co-amoxiclav contains amoxicillin, a penicillin, and carries the same cross-reactivity risk as the drug that previously caused her reaction.', 3),
('cb000000-0000-0000-0000-000000000001', 'D', 'Benzylpenicillin IV', false, 'Ruled out because benzylpenicillin is a penicillin; giving it to a patient with a likely IgE-mediated penicillin allergy risks a severe or anaphylactic reaction.', 4),
('cb000000-0000-0000-0000-000000000001', 'E', 'Piperacillin-tazobactam', false, 'Ruled out because this is a broad-spectrum penicillin-based antibiotic, both unnecessarily broad for uncomplicated cellulitis and unsafe given her penicillin allergy history.', 5),
('cb000000-0000-0000-0000-000000000002', 'A', 'Oral vancomycin', true, 'Correct. Oral vancomycin (or fidaxomicin) is the recommended first-line treatment for a first episode of C. difficile infection, as it acts locally within the gut lumen to eradicate the organism.', 1),
('cb000000-0000-0000-0000-000000000002', 'B', 'IV metronidazole', false, 'Ruled out because IV metronidazole does not reach adequate concentrations in the gut lumen for treating C. difficile colitis; oral therapy is required so the drug can act directly on the bowel.', 2),
('cb000000-0000-0000-0000-000000000002', 'C', 'Continue co-amoxiclav at a reduced dose', false, 'Ruled out because co-amoxiclav is the likely precipitant of this C. difficile infection and should be stopped, not continued, alongside starting specific treatment.', 3),
('cb000000-0000-0000-0000-000000000002', 'D', 'Loperamide alone', false, 'Ruled out because anti-motility agents are generally avoided in C. difficile infection, as they can slow clearance of toxin and increase the risk of toxic megacolon.', 4),
('cb000000-0000-0000-0000-000000000002', 'E', 'IV vancomycin', false, 'Ruled out because IV vancomycin does not achieve therapeutic concentrations within the bowel lumen; only the oral formulation is effective for C. difficile colitis.', 5),
('cb000000-0000-0000-0000-000000000003', 'A', 'Continue gentamicin at the same dose and reassess in 48 hours', false, 'Ruled out because continuing an ototoxic and nephrotoxic drug in the presence of early toxicity risks permanent hearing loss and worsening renal function.', 1),
('cb000000-0000-0000-0000-000000000003', 'B', 'Increase the gentamicin dose to ensure adequate treatment', false, 'Ruled out because increasing the dose of a drug already causing toxicity would worsen both the ototoxicity and nephrotoxicity.', 2),
('cb000000-0000-0000-0000-000000000003', 'C', 'Stop gentamicin, check a gentamicin level, and discuss ongoing antibiotic choice with microbiology', true, 'Correct. New tinnitus (ototoxicity) and rising creatinine (nephrotoxicity) are recognised, dose-related adverse effects of aminoglycosides; the drug should be stopped and levels checked, with microbiology input to select a safer alternative.', 3),
('cb000000-0000-0000-0000-000000000003', 'D', 'Switch immediately to oral gentamicin', false, 'Ruled out because gentamicin is not available or effective as an oral formulation due to negligible oral absorption; it is only given parenterally.', 4),
('cb000000-0000-0000-0000-000000000003', 'E', 'Add a regular NSAID for symptomatic relief', false, 'Ruled out because NSAIDs are themselves nephrotoxic and would compound the renal impairment already caused by the gentamicin.', 5),
('cb000000-0000-0000-0000-000000000004', 'A', 'Oral amoxicillin alone', false, 'Ruled out because oral monotherapy with a narrow-spectrum agent is inadequate for severe pneumonia with haemodynamic compromise and confusion; IV combination therapy is required.', 1),
('cb000000-0000-0000-0000-000000000004', 'B', 'IV benzylpenicillin alone', false, 'Ruled out because benzylpenicillin alone does not cover atypical organisms (e.g., Legionella, Mycoplasma) that must be covered in severe pneumonia.', 2),
('cb000000-0000-0000-0000-000000000004', 'C', 'IV vancomycin alone', false, 'Ruled out because vancomycin targets Gram-positive organisms including MRSA, but is not first-line empirical treatment for severe community-acquired pneumonia, which is usually due to Streptococcus pneumoniae and atypical pathogens.', 3),
('cb000000-0000-0000-0000-000000000004', 'D', 'Withhold antibiotics until sputum culture results are available', false, 'Ruled out because this is a medical emergency; empirical antibiotics must be started immediately without waiting for culture results, which take days.', 4),
('cb000000-0000-0000-0000-000000000004', 'E', 'IV co-amoxiclav plus clarithromycin', true, 'Correct. Severe community-acquired pneumonia (high CURB-65 score) requires broad-spectrum IV combination therapy covering typical and atypical organisms, such as a beta-lactam (co-amoxiclav) plus a macrolide (clarithromycin), given promptly.', 5),
('cb000000-0000-0000-0000-000000000005', 'A', 'Permanently discontinue vancomycin and document anaphylaxis', false, 'Ruled out because the absence of hypotension, wheeze, or angioedema, together with the classic flushing pattern, indicates red man syndrome rather than anaphylaxis; vancomycin can usually still be given safely at a slower rate.', 1),
('cb000000-0000-0000-0000-000000000005', 'B', 'Continue the infusion at the same rate without any intervention', false, 'Ruled out because continuing at the same rapid rate risks worsening flushing and potential hypotension; slowing the infusion is the appropriate response.', 2),
('cb000000-0000-0000-0000-000000000005', 'C', 'Give intramuscular adrenaline immediately', false, 'Ruled out because adrenaline is reserved for true anaphylaxis with airway, breathing or circulatory compromise, none of which are present here.', 3),
('cb000000-0000-0000-0000-000000000005', 'D', 'Stop the infusion temporarily, give an antihistamine if needed, and restart at a slower rate once symptoms settle', true, $x$Correct. This describes 'red man syndrome', a rate-related histamine reaction to vancomycin rather than a true allergy; it is managed by slowing the infusion rate (and pre-treating with antihistamines if it recurs), not by permanently discontinuing the drug.$x$, 4),
('cb000000-0000-0000-0000-000000000005', 'E', 'Switch immediately to an oral formulation of vancomycin', false, 'Ruled out because oral vancomycin is not systemically absorbed and would not treat a bloodstream infection such as MRSA bacteraemia.', 5),
('cb000000-0000-0000-0000-000000000006', 'A', 'An increased risk of tendon rupture', false, 'Ruled out because tendon rupture (particularly Achilles tendon) is a recognised adverse effect of fluoroquinolone antibiotics, not metronidazole.', 1),
('cb000000-0000-0000-0000-000000000006', 'B', 'A disulfiram-like reaction causing flushing, nausea and vomiting due to inhibition of acetaldehyde dehydrogenase', true, 'Correct. Metronidazole inhibits aldehyde dehydrogenase, leading to accumulation of acetaldehyde when alcohol is consumed, producing a disulfiram-like reaction of flushing, nausea, vomiting and headache.', 2),
('cb000000-0000-0000-0000-000000000006', 'C', 'Precipitation of red man syndrome', false, 'Ruled out because red man syndrome is a rate-related infusion reaction specific to IV vancomycin, unrelated to metronidazole or alcohol.', 3),
('cb000000-0000-0000-0000-000000000006', 'D', 'Precipitation of serotonin syndrome', false, 'Ruled out because serotonin syndrome relates to serotonergic drug combinations (e.g., linezolid with SSRIs), not to metronidazole and alcohol.', 4),
('cb000000-0000-0000-0000-000000000006', 'E', 'Significant QT interval prolongation', false, 'Ruled out because clinically significant QT prolongation is more characteristic of macrolides and some antiarrhythmics, not the alcohol interaction with metronidazole.', 5),
('cb000000-0000-0000-0000-000000000007', 'A', 'Urgent surgical referral for debridement, combined with immediate broad-spectrum IV antibiotics and resuscitation', true, 'Correct. This presentation (rapidly spreading erythema, crepitus, pain out of proportion to signs, systemic toxicity) is highly suggestive of necrotising fasciitis, a surgical emergency requiring urgent debridement alongside broad-spectrum antibiotics and haemodynamic resuscitation; delay significantly increases mortality.', 1),
('cb000000-0000-0000-0000-000000000007', 'B', 'Discharge home with oral flucloxacillin and outpatient review', false, 'Ruled out because this presentation reflects a life-threatening surgical emergency requiring immediate hospital admission, resuscitation and surgery, not outpatient oral antibiotics.', 2),
('cb000000-0000-0000-0000-000000000007', 'C', 'Elevate the limb and give analgesia only, reassessing in 24 hours', false, 'Ruled out because delaying definitive treatment in suspected necrotising fasciitis is dangerous; the condition progresses rapidly and carries high mortality without urgent intervention.', 3),
('cb000000-0000-0000-0000-000000000007', 'D', 'Arrange an MRI scan first and delay any treatment until imaging is reported', false, 'Ruled out because imaging should never delay surgical referral and empirical antibiotics when necrotising fasciitis is clinically suspected; the diagnosis is often made and acted upon clinically.', 4),
('cb000000-0000-0000-0000-000000000007', 'E', 'Give IV antibiotics alone and manage medically without surgical involvement', false, 'Ruled out because antibiotics alone cannot control necrotising fasciitis; surgical debridement of necrotic tissue is essential alongside antimicrobial therapy.', 5),
('cb000000-0000-0000-0000-000000000008', 'A', 'Amoxicillin (if the organism is sensitive)', false, 'Ruled out because amoxicillin is considered safe throughout pregnancy when the organism is sensitive, with no specific near-term restriction.', 1),
('cb000000-0000-0000-0000-000000000008', 'B', 'Cefalexin', false, 'Ruled out because cephalosporins such as cefalexin are considered safe to use throughout pregnancy, including near term.', 2),
('cb000000-0000-0000-0000-000000000008', 'C', 'Trimethoprim (in the third trimester)', false, $x$Ruled out because trimethoprim's main pregnancy risk relates to its folate-antagonist effect in the first trimester (neural tube defects); it does not carry the near-term neonatal haemolysis risk that nitrofurantoin does.$x$, 3),
('cb000000-0000-0000-0000-000000000008', 'D', 'Co-amoxiclav', false, 'Ruled out because co-amoxiclav is generally considered an acceptable alternative for UTI in pregnancy without this specific near-term concern.', 4),
('cb000000-0000-0000-0000-000000000008', 'E', 'Nitrofurantoin', true, 'Correct. Nitrofurantoin is generally avoided in the third trimester (near term) because of a theoretical risk of neonatal haemolysis if given shortly before delivery, related to immature neonatal red cell enzyme systems.', 5),
('cb000000-0000-0000-0000-000000000009', 'A', 'Nitrofurantoin', false, 'Ruled out because nitrofurantoin is considered safe for use in the first and second trimesters; its main restriction is near term (third trimester), not folate antagonism.', 1),
('cb000000-0000-0000-0000-000000000009', 'B', 'Ciprofloxacin', false, 'Ruled out because although fluoroquinolones are generally avoided in pregnancy, this is due to concerns about cartilage/joint effects, not a folate-antagonist mechanism.', 2),
('cb000000-0000-0000-0000-000000000009', 'C', 'Trimethoprim', true, 'Correct. Trimethoprim is a folate antagonist and is avoided in the first trimester because folate is essential for early fetal neural tube development, creating a theoretical teratogenic risk (neural tube defects).', 3),
('cb000000-0000-0000-0000-000000000009', 'D', 'Doxycycline', false, 'Ruled out because tetracyclines are avoided in pregnancy due to effects on fetal bone and teeth, not folate antagonism.', 4),
('cb000000-0000-0000-0000-000000000009', 'E', 'Co-trimoxazole', false, 'Ruled out because although co-trimoxazole does contain trimethoprim and shares this risk, it is not typically the first-line choice offered for a simple UTI in pregnancy in the first place, making it a less directly relevant answer than trimethoprim itself here.', 5),
('cb000000-0000-0000-0000-000000000010', 'A', 'Risk of red man syndrome', false, 'Ruled out because red man syndrome is specific to rapid IV vancomycin infusion, unrelated to tetracyclines.', 1),
('cb000000-0000-0000-0000-000000000010', 'B', 'Risk of tendon rupture', false, 'Ruled out because tendinopathy and tendon rupture are associated with fluoroquinolone antibiotics, not tetracyclines.', 2),
('cb000000-0000-0000-0000-000000000010', 'C', 'Risk of irreversible ototoxicity', false, 'Ruled out because ototoxicity is a recognised risk of aminoglycosides, not a primary concern with tetracyclines in children.', 3),
('cb000000-0000-0000-0000-000000000010', 'D', 'Risk of permanent tooth discolouration and enamel hypoplasia, and effects on developing bone', true, 'Correct. Tetracyclines bind to calcium in developing teeth and bone, causing permanent tooth discolouration, enamel hypoplasia, and potential effects on bone growth in young children, which is why they are generally avoided under the age of 12.', 4),
('cb000000-0000-0000-0000-000000000010', 'E', 'Increased risk of Clostridioides difficile infection specifically in children', false, 'Ruled out because although broad-spectrum antibiotics can precipitate C. difficile infection in any age group, this is not the specific, well-recognised reason tetracyclines are contraindicated in young children.', 5),
('cb000000-0000-0000-0000-000000000011', 'A', 'Start post-exposure prophylaxis (PEP) as soon as possible, ideally within hours and no later than 72 hours', true, 'Correct. PEP is most effective when started as soon as possible after high-risk exposure, ideally within hours; occupational health/emergency department should be contacted immediately to assess risk and initiate PEP without waiting for further test results.', 1),
('cb000000-0000-0000-0000-000000000011', 'B', $x$Wait for the source patient's repeat HIV viral load result before considering PEP$x$, false, 'Ruled out because PEP should not be delayed pending further results when the source is already known to be HIV-positive with a high viral load; delay reduces PEP effectiveness.', 2),
('cb000000-0000-0000-0000-000000000011', 'C', 'No action is needed as the risk from a hollow-bore needle injury is negligible', false, 'Ruled out because a needlestick injury from a blood-contaminated hollow-bore device carries a recognised, non-negligible transmission risk, particularly with a high viral load source.', 3),
('cb000000-0000-0000-0000-000000000011', 'D', 'Give the hepatitis B vaccine only, as this is the main risk from needlestick injuries', false, 'Ruled out because although hepatitis B and C exposure should also be assessed, HIV PEP is time-critical and must be addressed immediately given the known HIV-positive, high viral load source.', 4),
('cb000000-0000-0000-0000-000000000011', 'E', 'Start prophylactic antibiotics to prevent bacterial infection at the puncture site', false, 'Ruled out because antibiotics are not indicated for a clean needlestick wound; the priority is bloodborne virus risk assessment and PEP.', 5),
('cb000000-0000-0000-0000-000000000012', 'A', 'Refer to dermatology for the rash without testing for HIV', false, 'Ruled out because addressing the rash in isolation would miss the opportunity to identify an underlying HIV indicator presentation; an HIV test should be offered alongside dermatological assessment.', 1),
('cb000000-0000-0000-0000-000000000012', 'B', 'Offer an HIV test', true, 'Correct. Recurrent oral candidiasis, unexplained weight loss, night sweats and seborrhoeic dermatitis are recognised HIV indicator conditions; national guidance recommends offering an HIV test to any patient presenting with such features, regardless of disclosed risk factors.', 2),
('cb000000-0000-0000-0000-000000000012', 'C', 'Start empirical antifungal treatment and review in one month without testing', false, 'Ruled out because treating the candidiasis symptomatically without investigating the underlying cause would delay diagnosis of a potentially treatable underlying condition such as HIV.', 3),
('cb000000-0000-0000-0000-000000000012', 'D', 'Reassure the patient that this is a normal ageing process', false, 'Ruled out because this combination of features is not a normal ageing process and represents a recognised cluster of HIV indicator symptoms requiring testing.', 4),
('cb000000-0000-0000-0000-000000000012', 'E', 'Refer directly to oncology for investigation of malignancy without offering an HIV test', false, 'Ruled out because while unexplained weight loss can prompt cancer investigation, this specific combination of features (recurrent candidiasis, seborrhoeic dermatitis, night sweats) should first prompt an HIV test as a recognised indicator presentation.', 5),
('cb000000-0000-0000-0000-000000000013', 'A', 'Community-acquired bacterial pneumonia', false, 'Ruled out because bacterial pneumonia typically presents more acutely with focal consolidation and productive cough, rather than the subacute, bilateral interstitial pattern with exertional desaturation seen here.', 1),
('cb000000-0000-0000-0000-000000000013', 'B', 'Pulmonary tuberculosis', false, 'Ruled out because although TB is an important differential in HIV and should be actively excluded, the subacute bilateral interstitial pattern with marked exertional desaturation is more classically described for PCP.', 2),
('cb000000-0000-0000-0000-000000000013', 'C', 'Kaposi sarcoma with pulmonary involvement', false, 'Ruled out because pulmonary Kaposi sarcoma typically presents with nodular or endobronchial lesions and is far less common than PCP as a cause of this presentation.', 3),
('cb000000-0000-0000-0000-000000000013', 'D', 'Pneumocystis jirovecii pneumonia (PCP)', true, 'Correct. In a patient with advanced HIV (CD4 <200) presenting with subacute exertional dyspnoea, dry cough, exertional desaturation and bilateral interstitial infiltrates, PCP is the most likely diagnosis and requires urgent treatment.', 4),
('cb000000-0000-0000-0000-000000000013', 'E', 'Pulmonary embolism', false, 'Ruled out because the subacute two-week history and bilateral interstitial infiltrate pattern are not typical of an acute pulmonary embolism, and the low-grade fever and CD4 count point towards an opportunistic infection.', 5),
('cb000000-0000-0000-0000-000000000014', 'A', 'Amoxicillin', false, 'Ruled out because amoxicillin has no activity against Pneumocystis jirovecii and would not treat this opportunistic fungal-like infection.', 1),
('cb000000-0000-0000-0000-000000000014', 'B', 'Doxycycline', false, 'Ruled out because doxycycline is not first-line treatment for PCP; it may occasionally be used as part of alternative regimens in sulfa-allergic patients but is not the standard first-line choice.', 2),
('cb000000-0000-0000-0000-000000000014', 'C', 'Azithromycin', false, 'Ruled out because azithromycin is not effective treatment for PCP and is instead used for atypical bacterial pathogens or Mycobacterium avium complex prophylaxis.', 3),
('cb000000-0000-0000-0000-000000000014', 'D', 'Isoniazid', false, 'Ruled out because isoniazid is an anti-tuberculous agent and has no role in the treatment of Pneumocystis jirovecii pneumonia.', 4),
('cb000000-0000-0000-0000-000000000014', 'E', 'High-dose co-trimoxazole, with adjunctive corticosteroids given her hypoxia', true, 'Correct. High-dose co-trimoxazole (trimethoprim-sulfamethoxazole) is first-line treatment for PCP; adjunctive corticosteroids are added when there is moderate-to-severe hypoxia, as they reduce the inflammatory response and improve outcomes.', 5),
('cb000000-0000-0000-0000-000000000015', 'A', 'Primary CNS lymphoma', false, 'Ruled out as the most likely diagnosis because although it is an important differential producing a similar ring-enhancing appearance, it is typically a single lesion, whereas multiple lesions favour toxoplasmosis; toxoplasmosis is far more common overall.', 1),
('cb000000-0000-0000-0000-000000000015', 'B', 'Cryptococcal meningitis', false, 'Ruled out because cryptococcal disease usually presents as meningitis (headache, meningism, raised intracranial pressure) rather than focal ring-enhancing mass lesions with focal neurological deficits.', 2),
('cb000000-0000-0000-0000-000000000015', 'C', 'Cerebral toxoplasmosis', true, 'Correct. In advanced HIV (CD4 <100), multiple ring-enhancing lesions at the grey-white junction and basal ganglia with focal neurology and seizures are the classic presentation of cerebral toxoplasmosis, the most common cause of this pattern in this population.', 3),
('cb000000-0000-0000-0000-000000000015', 'D', 'Pyogenic bacterial brain abscess', false, 'Ruled out because although bacterial abscesses can appear as ring-enhancing lesions, this specific clinical context (advanced HIV, multiple lesions at grey-white junction/basal ganglia) is far more classically associated with toxoplasmosis.', 4),
('cb000000-0000-0000-0000-000000000015', 'E', 'Progressive multifocal leukoencephalopathy (PML)', false, 'Ruled out because PML typically causes non-enhancing white matter lesions without mass effect, in contrast to the ring-enhancing lesions with surrounding oedema described here.', 5),
('cb000000-0000-0000-0000-000000000016', 'A', 'A test performed now, at 2 weeks, is 100% reliable in excluding infection', false, 'Ruled out because at only 2 weeks post-exposure, even a fourth-generation test may not yet detect a very recent infection; a negative result this early is not fully reliable.', 1),
('cb000000-0000-0000-0000-000000000016', 'B', 'There is no point testing for HIV until 6 months after exposure', false, 'Ruled out because modern combined antigen/antibody testing has significantly shortened the reliable window period compared with older assays, and testing does not need to be delayed for six months.', 2),
('cb000000-0000-0000-0000-000000000016', 'C', 'A fourth-generation combined antigen/antibody test can give a reliable result from around 4 weeks after exposure, with a repeat test at 12 weeks to definitively exclude infection', true, 'Correct. Modern fourth-generation combined antigen/antibody assays reduce the diagnostic window period compared with older antibody-only tests, but a negative result very early after exposure cannot be fully relied upon; a repeat test at 12 weeks is recommended to definitively exclude infection.', 3),
('cb000000-0000-0000-0000-000000000016', 'D', 'Only an antibody-only test is available and should be used at 2 weeks', false, 'Ruled out because fourth-generation combined antigen/antibody tests are the standard of care and offer earlier detection than antibody-only assays.', 4),
('cb000000-0000-0000-0000-000000000016', 'E', 'Post-exposure prophylaxis is definitely not indicated because too much time has passed', false, 'Ruled out because although PEP is time-critical, decisions about PEP eligibility are separate from testing advice, and this statement does not correctly answer the question about testing reliability.', 5),
('cb000000-0000-0000-0000-000000000017', 'A', 'Delay ART until the CD4 count falls below 350 cells/microL', false, 'Ruled out because this reflects outdated practice; current guidance no longer waits for a CD4 threshold before starting treatment.', 1),
('cb000000-0000-0000-0000-000000000017', 'B', 'Delay ART until the patient becomes symptomatic', false, 'Ruled out because waiting for symptoms to develop would allow ongoing immune damage and transmission risk; early treatment is now standard regardless of symptoms.', 2),
('cb000000-0000-0000-0000-000000000017', 'C', 'ART should only be started once an opportunistic infection has occurred', false, 'Ruled out because this approach is outdated and unsafe; starting treatment only after an opportunistic infection develops means preventable immune deterioration has already occurred.', 3),
('cb000000-0000-0000-0000-000000000017', 'D', 'No ART is needed if the CD4 count is within the normal range', false, 'Ruled out because HIV treatment is now recommended for everyone diagnosed, regardless of CD4 count, to reduce viral replication, protect the immune system, and prevent transmission.', 4),
('cb000000-0000-0000-0000-000000000017', 'E', 'Start ART as soon as possible after diagnosis, regardless of CD4 count', true, 'Correct. Current guidance recommends offering ART to all people diagnosed with HIV as soon as possible after diagnosis, irrespective of CD4 count, both to improve individual outcomes and to reduce onward transmission risk.', 5),
('cb000000-0000-0000-0000-000000000018', 'A', 'Neisseria meningitidis', false, 'Ruled out because meningococcal meningitis typically presents acutely (over hours) with high fever, marked meningism, and often a non-blanching rash, rather than the subacute picture with encapsulated yeast on India ink staining described here.', 1),
('cb000000-0000-0000-0000-000000000018', 'B', 'Cryptococcus neoformans', true, 'Correct. Cryptococcal meningitis classically occurs in advanced HIV (CD4 <100), presenting with subacute headache, low-grade fever and raised intracranial pressure; India ink staining showing encapsulated yeast is diagnostic of Cryptococcus neoformans.', 2),
('cb000000-0000-0000-0000-000000000018', 'C', 'Listeria monocytogenes', false, 'Ruled out because Listeria meningitis is a bacterial infection typically affecting neonates, the elderly, or immunosuppressed patients with a different CSF profile, and would not show encapsulated yeast on India ink stain.', 3),
('cb000000-0000-0000-0000-000000000018', 'D', 'Mycobacterium tuberculosis', false, 'Ruled out because although TB meningitis is an important differential in HIV with a similarly subacute course, it would not show encapsulated yeast forms on India ink staining, which is specific to Cryptococcus.', 4),
('cb000000-0000-0000-0000-000000000018', 'E', 'Streptococcus pneumoniae', false, 'Ruled out because pneumococcal meningitis is bacterial, typically more acute in onset, and would not show encapsulated yeast on India ink staining.', 5),
('cb000000-0000-0000-0000-000000000019', 'A', 'Sputum samples for acid-fast bacilli smear, culture, and nucleic acid amplification testing', true, 'Correct. TB is more common and often presents atypically (without classic cavitation) in people with HIV, particularly with lower CD4 counts; sputum should be sent for AFB smear, culture and molecular testing to confirm or exclude the diagnosis.', 1),
('cb000000-0000-0000-0000-000000000019', 'B', 'Reassurance that this represents a self-limiting viral illness', false, 'Ruled out because a 3-month history of cough, weight loss and night sweats in an HIV-positive patient is a red flag for serious underlying pathology such as TB and must be actively investigated.', 2),
('cb000000-0000-0000-0000-000000000019', 'C', 'Start empirical antibiotics for community-acquired pneumonia only, without further investigation', false, 'Ruled out because this chronic, systemic presentation with weight loss and night sweats is not typical of straightforward bacterial pneumonia, and empirical treatment without investigating for TB risks missing the diagnosis and ongoing transmission.', 3),
('cb000000-0000-0000-0000-000000000019', 'D', 'No further action is required as the chest X-ray does not show cavitation', false, 'Ruled out because TB in HIV-positive patients, especially with lower CD4 counts, frequently presents atypically without cavitation; a normal or non-classic chest X-ray does not exclude TB.', 4),
('cb000000-0000-0000-0000-000000000019', 'E', 'Refer directly to oncology for investigation of presumed malignancy without considering infection', false, 'Ruled out because although malignancy can cause similar systemic symptoms, TB is a key and treatable differential that must be actively excluded first in this at-risk HIV-positive patient.', 5),
('cb000000-0000-0000-0000-000000000020', 'A', 'Reassure her that no action is needed as the exposure was too long ago', false, 'Ruled out because 30 hours is well within the 72-hour window in which PEPSE remains effective and should be offered.', 1),
('cb000000-0000-0000-0000-000000000020', 'B', 'Arrange an HIV test only, with no discussion of PEP', false, 'Ruled out because testing alone at this stage would not detect a very recent exposure and would miss the opportunity to prevent infection with timely PEP.', 2),
('cb000000-0000-0000-0000-000000000020', 'C', $x$PEP should only be offered once the partner's HIV status is confirmed positive$x$, false, $x$Ruled out because waiting for confirmation of the partner's status would cause unacceptable delay; PEP decisions are based on risk assessment of the exposure, and delay reduces effectiveness.$x$, 3),
('cb000000-0000-0000-0000-000000000020', 'D', 'Offer post-exposure prophylaxis following sexual exposure (PEPSE), started as soon as possible', true, 'Correct. PEPSE should be offered and started as soon as possible after a high-risk sexual exposure, ideally within hours and no later than 72 hours, to reduce the risk of HIV acquisition.', 4),
('cb000000-0000-0000-0000-000000000020', 'E', 'Refer to a sexual health clinic for review in two weeks', false, 'Ruled out because PEP is time-critical and must be assessed and started urgently (ideally within hours, and no later than 72 hours), not deferred for two weeks.', 5),
('cb000000-0000-0000-0000-000000000021', 'A', 'Proceed straight to surgery without any additional treatment', false, 'Ruled out because proceeding without decolonisation increases the risk of MRSA surgical site infection, which decolonisation aims to reduce.', 1),
('cb000000-0000-0000-0000-000000000021', 'B', 'Give IV vancomycin prophylaxis alone without any decolonisation regimen', false, 'Ruled out because although MRSA-positive patients may also receive glycopeptide antibiotic prophylaxis at the time of surgery, this does not replace the need for pre-operative topical decolonisation.', 2),
('cb000000-0000-0000-0000-000000000021', 'C', 'Cancel the surgery indefinitely until repeat swabs are negative', false, 'Ruled out because elective surgery is not usually cancelled indefinitely for MRSA colonisation; decolonisation is carried out and surgery can generally proceed with appropriate precautions.', 3),
('cb000000-0000-0000-0000-000000000021', 'D', 'Treat with a course of oral flucloxacillin to eradicate carriage', false, 'Ruled out because oral flucloxacillin would be ineffective against MRSA (which is resistant to flucloxacillin by definition) and systemic antibiotics are not used to eradicate asymptomatic nasal/skin carriage.', 4),
('cb000000-0000-0000-0000-000000000021', 'E', 'Decolonisation with topical nasal mupirocin and chlorhexidine body washes prior to surgery', true, 'Correct. Patients found to be MRSA carriers on pre-operative screening should undergo a decolonisation regimen (nasal mupirocin and antiseptic body wash) to reduce the risk of surgical site infection before proceeding to elective surgery.', 5),
('cb000000-0000-0000-0000-000000000022', 'A', 'Alcohol-based hand gel alone is sufficient before and after contact', false, 'Ruled out because alcohol gel does not reliably kill or remove C. difficile spores, and relying on it alone risks ongoing transmission.', 1),
('cb000000-0000-0000-0000-000000000022', 'B', 'Hand hygiene should be performed with soap and water, as alcohol-based hand gel does not kill C. difficile spores', true, 'Correct. C. difficile forms spores that are resistant to alcohol-based hand gels; washing with soap and water is required to mechanically remove spores from the hands.', 2),
('cb000000-0000-0000-0000-000000000022', 'C', 'No isolation or specific precautions are needed for C. difficile infection', false, 'Ruled out because C. difficile is highly transmissible via spores and requires single-room isolation with contact precautions to prevent spread to other patients.', 3),
('cb000000-0000-0000-0000-000000000022', 'D', 'PPE is not required as C. difficile is not transmissible between patients', false, 'Ruled out because C. difficile spores are readily transmitted via hands and the environment; appropriate PPE (gloves, apron) and isolation are essential.', 4),
('cb000000-0000-0000-0000-000000000022', 'E', 'The patient should be discharged home immediately regardless of clinical state to reduce ward transmission risk', false, 'Ruled out because discharge decisions must be based on clinical fitness for discharge, not solely on infection control convenience; appropriate isolation on the ward is the correct interim measure.', 5),
('cb000000-0000-0000-0000-000000000023', 'A', 'Start empirical antibiotics for asymptomatic bacteriuria', false, 'Ruled out because treating asymptomatic bacteriuria with antibiotics is not recommended (except in specific situations such as pregnancy or prior to urological procedures) and contributes to antimicrobial resistance.', 1),
('cb000000-0000-0000-0000-000000000023', 'B', 'Leave the catheter in place indefinitely as it was already inserted', false, 'Ruled out because unnecessary catheters should be removed promptly, as prolonged catheterisation increases the risk of catheter-associated infection.', 2),
('cb000000-0000-0000-0000-000000000023', 'C', 'Review the ongoing need for the catheter and remove it if no longer clinically indicated; do not treat asymptomatic bacteriuria', true, 'Correct. Urinary catheters should only be used when clinically indicated and removed as soon as possible to reduce catheter-associated UTI risk. Cloudy urine in an asymptomatic patient represents asymptomatic bacteriuria, which does not require antibiotic treatment.', 3),
('cb000000-0000-0000-0000-000000000023', 'D', 'Change the catheter prophylactically to prevent infection', false, 'Ruled out because routine catheter changes do not prevent catheter-associated UTI and are not indicated in an asymptomatic patient; the priority is reviewing whether the catheter is needed at all.', 4),
('cb000000-0000-0000-0000-000000000023', 'E', 'Send a urine culture and treat with antibiotics regardless of symptoms', false, 'Ruled out because treating culture-positive but asymptomatic bacteriuria is not indicated and promotes unnecessary antibiotic use and resistance.', 5),
('cb000000-0000-0000-0000-000000000024', 'A', 'Within 60 minutes before skin incision', true, 'Correct. Surgical antibiotic prophylaxis should be administered within 60 minutes prior to skin incision to ensure adequate tissue concentrations are present at the time of the highest contamination risk.', 1),
('cb000000-0000-0000-0000-000000000024', 'B', 'Immediately after wound closure', false, 'Ruled out because giving prophylaxis after the wound has already been closed means the antibiotic is not present during the period of surgical contamination risk, reducing its effectiveness.', 2),
('cb000000-0000-0000-0000-000000000024', 'C', '24 hours before surgery as a single pre-admission dose', false, 'Ruled out because antibiotic levels given this far in advance would not be at effective tissue concentrations at the time of incision.', 3),
('cb000000-0000-0000-0000-000000000024', 'D', 'Only if a surgical site infection develops post-operatively', false, 'Ruled out because this describes treatment of an established infection, not prophylaxis, which is intended to prevent infection from occurring in the first place.', 4),
('cb000000-0000-0000-0000-000000000024', 'E', 'As a routine two-week postoperative course regardless of clinical progress', false, 'Ruled out because prolonged prophylactic courses are not recommended and increase the risk of antimicrobial resistance and adverse effects without added benefit over a single well-timed pre-incision dose.', 5),
('cb000000-0000-0000-0000-000000000025', 'A', 'Community-acquired bacteraemia unrelated to the line', false, 'Ruled out because the differential time to positivity pattern specifically implicates the central line as the source, rather than an unrelated community-acquired process.', 1),
('cb000000-0000-0000-0000-000000000025', 'B', 'Contaminated blood culture sample with no true infection', false, 'Ruled out because concordant growth of the same organism from two separate sites with a clear differential time to positivity pattern is consistent with true bacteraemia from the line, not simple contamination.', 2),
('cb000000-0000-0000-0000-000000000025', 'C', 'Infective endocarditis', false, 'Ruled out because there is no mention of a new murmur, embolic phenomena, or echocardiographic findings; the clinical and microbiological pattern described is specific for a line-related bloodstream infection.', 3),
('cb000000-0000-0000-0000-000000000025', 'D', 'Central line-associated bloodstream infection (CLABSI)', true, 'Correct. Growth of the same organism from both central and peripheral samples, with the central line sample becoming positive significantly earlier (differential time to positivity), is a recognised diagnostic feature of a central line-associated bloodstream infection.', 4),
('cb000000-0000-0000-0000-000000000025', 'E', 'Urinary tract infection with secondary bacteraemia', false, 'Ruled out because there is no mention of urinary symptoms or urine culture findings, and the differential time to positivity pattern specifically points to the central line as the source.', 5),
('cb000000-0000-0000-0000-000000000026', 'A', 'Continue normal ward admissions as usual', false, 'Ruled out because continuing to admit new patients to an affected ward during a likely norovirus outbreak risks further transmission to vulnerable patients.', 1),
('cb000000-0000-0000-0000-000000000026', 'B', 'Treat all affected individuals with broad-spectrum antibiotics', false, 'Ruled out because norovirus is a viral infection; antibiotics have no role in its treatment and would not be appropriate management.', 2),
('cb000000-0000-0000-0000-000000000026', 'C', 'Rely on alcohol-based hand gel alone without isolation measures', false, 'Ruled out because, similar to C. difficile, norovirus is not reliably inactivated by alcohol gel alone; isolation and soap-and-water hand hygiene are important components of outbreak control.', 3),
('cb000000-0000-0000-0000-000000000026', 'D', 'Close the ward to new admissions and isolate affected patients until they have been symptom-free for at least 48 hours', true, 'Correct. This clinical pattern is typical of a norovirus outbreak; affected wards should be closed to new admissions/transfers and affected individuals isolated (cohorted) until 48 hours symptom-free, to limit further spread.', 4),
('cb000000-0000-0000-0000-000000000026', 'E', 'Discharge all affected patients home immediately regardless of their clinical condition', false, 'Ruled out because discharge decisions should be based on clinical fitness, not solely on outbreak control; the correct approach is ward closure and isolation while managing patients appropriately.', 5),
('cb000000-0000-0000-0000-000000000027', 'A', 'Suck the wound to remove as much blood as possible', false, 'Ruled out because sucking the wound is not recommended and does not provide protective benefit; the correct first-aid step is washing with soap and water.', 1),
('cb000000-0000-0000-0000-000000000027', 'B', 'Ignore the injury as the risk is likely to be low', false, $x$Ruled out because all sharps injuries should be reported and assessed, as risk cannot be reliably judged without formal evaluation and knowledge of the source patient's status.$x$, 2),
('cb000000-0000-0000-0000-000000000027', 'C', 'Wash the wound thoroughly with soap and water (without sucking the wound), encourage bleeding, and then report the injury to occupational health', true, 'Correct. The immediate first-aid steps for a sharps injury are to wash the site thoroughly with soap and running water, encourage the wound to bleed freely, avoid sucking the wound, and then report promptly to occupational health or the relevant local protocol for risk assessment and further management.', 3),
('cb000000-0000-0000-0000-000000000027', 'D', 'Apply antiseptic and a dressing, with no further reporting needed', false, 'Ruled out because formal reporting to occupational health (or equivalent) is essential so a proper risk assessment and, if needed, prophylaxis can be arranged promptly.', 4),
('cb000000-0000-0000-0000-000000000027', 'E', 'Wait until the end of the shift to report the injury', false, 'Ruled out because reporting should happen immediately, as risk assessment and any indicated post-exposure prophylaxis are time-critical and most effective when started as soon as possible.', 5),
('cb000000-0000-0000-0000-000000000028', 'A', 'Treat with IV vancomycin to eradicate carriage', false, 'Ruled out because the organism is, by definition, resistant to vancomycin, making this an ineffective and inappropriate treatment choice.', 1),
('cb000000-0000-0000-0000-000000000028', 'B', 'Implement contact precautions/isolation; no antibiotic treatment is needed as this represents asymptomatic colonisation', true, 'Correct. Asymptomatic colonisation with VRE does not require antibiotic treatment, but contact precautions (single room, gloves and apron, dedicated equipment where possible) should be implemented to prevent transmission to other patients.', 2),
('cb000000-0000-0000-0000-000000000028', 'C', 'Treat with linezolid regardless of the absence of clinical infection', false, 'Ruled out because antibiotic treatment (such as linezolid) is reserved for active VRE infection, not asymptomatic colonisation, to avoid unnecessary antibiotic exposure and resistance selection.', 3),
('cb000000-0000-0000-0000-000000000028', 'D', 'No infection control measures are required as the patient is asymptomatic', false, 'Ruled out because asymptomatic colonisation with a multidrug-resistant organism such as VRE still requires contact precautions to prevent spread to other vulnerable patients.', 4),
('cb000000-0000-0000-0000-000000000028', 'E', 'Discharge immediately without any precautions or documentation', false, 'Ruled out because discharge planning should include appropriate documentation of colonisation status and, where relevant, communication with receiving care settings, not simply proceeding without any precautions.', 5),
('cb000000-0000-0000-0000-000000000029', 'A', 'Only when hands are visibly soiled', false, 'Ruled out because hand hygiene is required at defined clinical moments regardless of visible soiling, not only when hands appear dirty.', 1),
('cb000000-0000-0000-0000-000000000029', 'B', 'Only immediately before an invasive procedure', false, 'Ruled out because this describes only one of the five moments (before a clean/aseptic procedure) and omits the other required moments of hand hygiene during patient contact.', 2),
('cb000000-0000-0000-0000-000000000029', 'C', 'Only at the start and end of a shift', false, 'Ruled out because hand hygiene must be performed at multiple points throughout every patient interaction, not just once at the start and end of a shift.', 3),
('cb000000-0000-0000-0000-000000000029', 'D', 'Only after removing gloves, and at no other point', false, 'Ruled out because although hand hygiene is required after removing gloves, this is only one of several required moments, not the sole occasion.', 4),
('cb000000-0000-0000-0000-000000000029', 'E', 'Before touching a patient', true, $x$Correct. 'Before touching a patient' is one of the WHO's five moments for hand hygiene, alongside before a clean/aseptic procedure, after body fluid exposure risk, after touching a patient, and after touching a patient's surroundings.$x$, 5),
('cb000000-0000-0000-0000-000000000030', 'A', 'Airborne precautions in a single room, ideally with negative pressure ventilation', true, 'Correct. Suspected or confirmed smear-positive pulmonary TB requires airborne precautions, ideally in a negative pressure single room, to prevent transmission of infectious droplet nuclei to other patients and staff.', 1),
('cb000000-0000-0000-0000-000000000030', 'B', 'Standard precautions on an open bay with no isolation', false, 'Ruled out because smear-positive pulmonary TB is highly infectious via the airborne route and requires isolation, not management on an open bay.', 2),
('cb000000-0000-0000-0000-000000000030', 'C', 'Contact precautions only, without airborne precautions', false, 'Ruled out because TB transmission is via the airborne route (droplet nuclei), not primarily by direct contact, so airborne precautions (not just contact precautions) are required.', 3),
('cb000000-0000-0000-0000-000000000030', 'D', 'No isolation is needed until the diagnosis is microbiologically confirmed', false, 'Ruled out because isolation should begin as soon as TB is clinically suspected (based on symptoms and a strongly suggestive smear), not delayed until full confirmation, given the risk of onward transmission.', 4),
('cb000000-0000-0000-0000-000000000030', 'E', 'Droplet precautions in a shared bay with other respiratory patients', false, 'Ruled out because TB requires specific airborne precautions in a single (ideally negative pressure) room, not droplet precautions in a shared bay, due to the risk of transmitting infectious droplet nuclei over longer distances and time in air.', 5),
('cb000000-0000-0000-0000-000000000031', 'A', 'Wait for senior review before starting any treatment', false, 'Ruled out because sepsis is a time-critical emergency; the Sepsis Six should be started immediately by the attending clinician without waiting for senior review to begin treatment.', 1),
('cb000000-0000-0000-0000-000000000031', 'B', 'Give oral antibiotics only', false, 'Ruled out because a patient with this degree of haemodynamic compromise and confusion requires IV, not oral, antibiotics, to ensure adequate and rapid systemic drug levels.', 2),
('cb000000-0000-0000-0000-000000000031', 'C', 'Give antipyretics alone and reassess in 4 hours', false, 'Ruled out because antipyretics alone do not address the underlying infective process or haemodynamic compromise; the full Sepsis Six bundle is required within one hour.', 3),
('cb000000-0000-0000-0000-000000000031', 'D', 'The Sepsis Six: take blood cultures, measure lactate, monitor urine output, give high-flow oxygen, give IV fluids, and give IV broad-spectrum antibiotics', true, 'Correct. The Sepsis Six bundle should be delivered within one hour of recognising sepsis: blood cultures, serum lactate, urine output monitoring, high-flow oxygen, IV fluid resuscitation, and IV broad-spectrum antibiotics, to reduce mortality from delayed treatment.', 4),
('cb000000-0000-0000-0000-000000000031', 'E', 'Arrange a CT abdomen before starting any treatment', false, 'Ruled out because imaging must not delay the time-critical Sepsis Six interventions; source identification via imaging can follow once initial resuscitation and antibiotics have been started.', 5),
('cb000000-0000-0000-0000-000000000032', 'A', 'APGAR score', false, 'Ruled out because the APGAR score is used to assess the condition of a newborn infant immediately after birth, not to detect clinical deterioration or sepsis in adult ward patients.', 1),
('cb000000-0000-0000-0000-000000000032', 'B', 'National Early Warning Score 2 (NEWS2)', true, 'Correct. NEWS2 is the standard track-and-trigger early warning score used across UK hospitals to identify patients who are deteriorating, including those developing sepsis, based on physiological parameters such as respiratory rate, oxygen saturation, blood pressure, heart rate, level of consciousness and temperature.', 2),
('cb000000-0000-0000-0000-000000000032', 'C', 'Glasgow-Blatchford score', false, 'Ruled out because this score is used to risk-stratify patients with upper gastrointestinal bleeding, not general ward deterioration or sepsis.', 3),
('cb000000-0000-0000-0000-000000000032', 'D', 'CURB-65', false, 'Ruled out because CURB-65 is specific to assessing severity in community-acquired pneumonia, not a general early warning score for ward deterioration.', 4),
('cb000000-0000-0000-0000-000000000032', 'E', 'Wells score', false, 'Ruled out because the Wells score is used to estimate the pre-test probability of venous thromboembolism, not to detect general clinical deterioration.', 5),
('cb000000-0000-0000-0000-000000000033', 'A', 'Give further unlimited fluid boluses without escalating care', false, 'Ruled out because continuing to give large volumes of fluid without vasopressor support or senior/critical care input risks fluid overload without correcting the underlying shock, and delays appropriate escalation.', 1),
('cb000000-0000-0000-0000-000000000033', 'B', 'Switch to oral antibiotics as the patient is already on treatment', false, 'Ruled out because a patient in septic shock requires ongoing IV antibiotics, and this option does not address the immediate haemodynamic instability at all.', 2),
('cb000000-0000-0000-0000-000000000033', 'C', 'Give a blood transfusion regardless of his haemoglobin level', false, 'Ruled out because blood transfusion is not indicated based on haemodynamic instability alone without evidence of significant blood loss or a specific transfusion threshold being met.', 3),
('cb000000-0000-0000-0000-000000000033', 'D', 'Discharge home for outpatient follow-up once physically able to mobilise', false, 'Ruled out because a patient with fluid-refractory septic shock requires urgent escalation and likely critical care admission, not discharge.', 4),
('cb000000-0000-0000-0000-000000000033', 'E', 'Start a vasopressor (e.g., noradrenaline) and refer urgently for critical care review', true, 'Correct. Persistent hypotension despite adequate fluid resuscitation (fluid-refractory septic shock) requires vasopressor support, typically noradrenaline, and urgent critical care involvement for ongoing management.', 5),
('cb000000-0000-0000-0000-000000000034', 'A', 'Give immediate IV broad-spectrum antibiotics (e.g., piperacillin-tazobactam) within one hour, without delay', true, 'Correct. Neutropenic sepsis is a medical emergency; broad-spectrum IV antibiotics (such as piperacillin-tazobactam) must be given within one hour of presentation in any febrile patient with known or suspected significant neutropenia, without waiting for confirmatory blood results.', 1),
('cb000000-0000-0000-0000-000000000034', 'B', 'Wait for the full blood count result to confirm neutropenia before starting antibiotics', false, 'Ruled out because any suspicion of neutropenic sepsis (fever in a patient recently treated with chemotherapy) should prompt immediate empirical antibiotics; waiting for confirmatory results causes dangerous delay.', 2),
('cb000000-0000-0000-0000-000000000034', 'C', 'Treat as an outpatient with oral antibiotics', false, 'Ruled out because neutropenic sepsis requires urgent hospital admission and IV antibiotics, not outpatient oral treatment, due to the high risk of rapid deterioration.', 3),
('cb000000-0000-0000-0000-000000000034', 'D', 'Give antipyretics only and observe for 24 hours', false, 'Ruled out because this delays definitive treatment of a life-threatening emergency; antibiotics must be started immediately, not observation alone.', 4),
('cb000000-0000-0000-0000-000000000034', 'E', 'Delay antibiotics until blood culture results are available', false, 'Ruled out because blood cultures should be taken but must not delay the administration of empirical antibiotics, which should be given within one hour.', 5),
('cb000000-0000-0000-0000-000000000035', 'A', 'Give the antibiotics first, then take blood cultures the following day', false, 'Ruled out because taking cultures after antibiotics have already been given significantly reduces the chance of identifying the causative organism.', 1),
('cb000000-0000-0000-0000-000000000035', 'B', 'Skip blood cultures altogether to save time', false, 'Ruled out because blood cultures are an essential part of the Sepsis Six bundle, providing crucial information to guide ongoing antibiotic therapy.', 2),
('cb000000-0000-0000-0000-000000000035', 'C', 'Take blood cultures immediately, before administering the first dose of antibiotics', true, 'Correct. Blood cultures should be taken before the first dose of antibiotics wherever possible, as antibiotics can reduce the yield of subsequent cultures; however, this must not delay antibiotic administration beyond the target one-hour window.', 3),
('cb000000-0000-0000-0000-000000000035', 'D', 'Wait for microbiology approval before taking blood cultures', false, 'Ruled out because blood cultures are a routine, immediately available bedside investigation that does not require prior microbiology approval.', 4),
('cb000000-0000-0000-0000-000000000035', 'E', 'Delay antibiotics until blood culture results are available', false, 'Ruled out because antibiotics must be given within one hour of recognising sepsis; waiting days for culture results would cause dangerous, unacceptable delay.', 5),
('cb000000-0000-0000-0000-000000000036', 'A', 'Continue antibiotics alone without any surgical intervention', false, 'Ruled out because antibiotics alone are unlikely to resolve a well-formed abscess; source control via drainage is essential when a collection is present and the patient remains septic.', 1),
('cb000000-0000-0000-0000-000000000036', 'B', 'Urgent surgical drainage of the abscess (source control)', true, 'Correct. An abscess is a collection that antibiotics alone cannot adequately penetrate or resolve; ongoing sepsis despite appropriate antibiotics indicates the need for urgent source control via surgical drainage.', 2),
('cb000000-0000-0000-0000-000000000036', 'C', 'Increase the antibiotic dose only, without considering drainage', false, 'Ruled out because simply increasing antibiotic dosing does not address the underlying undrained collection driving ongoing sepsis.', 3),
('cb000000-0000-0000-0000-000000000036', 'D', 'Discharge home on oral antibiotics given some initial treatment has been given', false, 'Ruled out because the patient remains systemically unwell with ongoing fever and worsening pain; discharge would be unsafe without addressing the underlying source.', 4),
('cb000000-0000-0000-0000-000000000036', 'E', 'Wait a further 48 hours before considering any surgical intervention', false, 'Ruled out because further delay in a patient failing to improve on antibiotics risks worsening sepsis; urgent source control should not be delayed once failure of medical management is apparent.', 5),
('cb000000-0000-0000-0000-000000000037', 'A', 'Start antibiotics immediately without taking blood cultures', false, 'Ruled out because starting antibiotics before cultures are taken in suspected endocarditis can prevent identification of the causative organism, which is critical for selecting the correct prolonged antibiotic regimen.', 1),
('cb000000-0000-0000-0000-000000000037', 'B', 'Arrange a CT chest only, without blood cultures', false, 'Ruled out because CT chest is not the key initial investigation for suspected endocarditis; blood cultures and echocardiography are the priority investigations.', 2),
('cb000000-0000-0000-0000-000000000037', 'C', 'Send a urine culture only', false, 'Ruled out because urine culture would not identify the causative organism in suspected endocarditis; blood cultures are required.', 3),
('cb000000-0000-0000-0000-000000000037', 'D', 'Take three sets of blood cultures from different venepuncture sites before starting antibiotics', true, 'Correct. In suspected infective endocarditis, multiple sets (typically three) of blood cultures from different sites should be taken before starting antibiotics, as this maximises the chance of identifying the causative organism, which is essential for guiding prolonged targeted therapy.', 4),
('cb000000-0000-0000-0000-000000000037', 'E', 'Skip cultures and treat empirically with a short course of oral antibiotics', false, 'Ruled out because infective endocarditis requires prolonged, targeted IV antibiotic therapy guided by blood culture results, not an empirical short oral course.', 5),
('cb000000-0000-0000-0000-000000000038', 'A', 'Wait for hospital assessment before giving any antibiotics', false, 'Ruled out because pre-hospital antibiotics should not be delayed in suspected meningococcal disease, as early treatment significantly improves outcomes in this rapidly progressive, life-threatening condition.', 1),
('cb000000-0000-0000-0000-000000000038', 'B', 'Prescribe oral antibiotics and review again in the community tomorrow', false, 'Ruled out because oral antibiotics are inadequate for suspected meningococcal sepsis, and any delay in hospital transfer risks rapid deterioration and death.', 2),
('cb000000-0000-0000-0000-000000000038', 'C', 'Reassure the patient and review again in 24 hours', false, 'Ruled out because this presentation represents a medical emergency requiring immediate treatment and transfer, not reassurance and delayed review.', 3),
('cb000000-0000-0000-0000-000000000038', 'D', 'Give an antihistamine for the rash and arrange routine follow-up', false, 'Ruled out because a non-blanching purpuric rash with fever and meningism is not an allergic phenomenon; it is a red flag for meningococcal sepsis requiring emergency treatment.', 4),
('cb000000-0000-0000-0000-000000000038', 'E', 'Give intramuscular or intravenous benzylpenicillin immediately and arrange emergency transfer to hospital', true, 'Correct. Suspected meningococcal sepsis with a non-blanching rash and meningism is a life-threatening emergency; benzylpenicillin should be given as soon as possible in the pre-hospital setting (unless there is a clear history of severe allergy), followed by immediate emergency transfer to hospital.', 5),
('cb000000-0000-0000-0000-000000000039', 'A', 'A normal finding that requires no further action', false, 'Ruled out because a lactate of 4.2 mmol/L is significantly elevated and reflects ongoing physiological compromise requiring active management, not reassurance.', 1),
('cb000000-0000-0000-0000-000000000039', 'B', 'Isolated evidence of renal failure with no other significance', false, 'Ruled out because although lactate clearance can be affected by renal function, in the context of sepsis a raised lactate primarily reflects tissue hypoperfusion, not renal failure specifically.', 2),
('cb000000-0000-0000-0000-000000000039', 'C', 'Ongoing tissue hypoperfusion, suggesting inadequate resuscitation and the need for further urgent review (e.g., further fluids, vasopressor consideration, and senior/critical care input)', true, 'Correct. A persistently elevated lactate after initial resuscitation reflects ongoing tissue hypoperfusion and anaerobic metabolism, indicating the patient requires further urgent reassessment and escalation of treatment rather than reassurance.', 3),
('cb000000-0000-0000-0000-000000000039', 'D', 'Isolated evidence of liver failure with no other significance', false, 'Ruled out because although the liver metabolises lactate, in the context of sepsis a persistently raised lactate is primarily interpreted as a marker of ongoing tissue hypoperfusion requiring urgent action.', 4),
('cb000000-0000-0000-0000-000000000039', 'E', 'Confirmation that the underlying infection has resolved', false, 'Ruled out because a persistently elevated lactate indicates ongoing physiological compromise, not resolution of the underlying septic process.', 5),
('cb000000-0000-0000-0000-000000000040', 'A', 'This may represent urosepsis presenting atypically without fever, given her age; she should undergo urgent assessment and the Sepsis Six bundle should be considered as clinically indicated', true, 'Correct. Elderly patients frequently present with sepsis atypically, often without a significant fever, and instead with non-specific features such as new confusion, tachycardia, tachypnoea, and reduced oral intake; sepsis must not be excluded on the basis of a normal or low temperature alone.', 1),
('cb000000-0000-0000-0000-000000000040', 'B', 'Sepsis can be excluded because she is afebrile', false, 'Ruled out because absence of fever does not exclude sepsis, particularly in elderly or frail patients who often mount a blunted febrile response despite significant infection.', 2),
('cb000000-0000-0000-0000-000000000040', 'C', 'This most likely represents progression of dementia only, and no further infective workup is needed', false, 'Ruled out because new, acute confusion in an elderly patient with abnormal observations and foul-smelling urine should prompt active investigation for an underlying infective or other acute cause, not be attributed to baseline dementia without assessment.', 3),
('cb000000-0000-0000-0000-000000000040', 'D', 'Reassure the family and review again in a week', false, 'Ruled out because acute new confusion with abnormal vital signs requires urgent same-day assessment, not deferred review.', 4),
('cb000000-0000-0000-0000-000000000040', 'E', 'Discharge back to the care home without any further investigation', false, 'Ruled out because this presentation requires urgent assessment for a possible underlying source of sepsis before any discharge decision can safely be made.', 5),
('cb000000-0000-0000-0000-000000000041', 'A', 'Stool microscopy for ova, cysts and parasites', false, 'Ruled out because this presentation (cyclical fever, rigors, myalgia) without gastrointestinal symptoms is not suggestive of a gastrointestinal parasitic infection; malaria must be excluded first given the travel history.', 1),
('cb000000-0000-0000-0000-000000000041', 'B', 'Chest X-ray', false, 'Ruled out because there are no respiratory symptoms described, and a chest X-ray would not identify the likely underlying cause (malaria) suggested by this travel history and fever pattern.', 2),
('cb000000-0000-0000-0000-000000000041', 'C', 'Thick and thin blood films for malaria parasites', true, 'Correct. In any returning traveller from a malaria-endemic area presenting with fever, thick and thin blood films (or a rapid diagnostic test) are the essential first investigation to identify and quantify malaria parasitaemia; malaria must always be actively excluded given its potential severity.', 3),
('cb000000-0000-0000-0000-000000000041', 'D', 'Throat swab for group A streptococcus', false, 'Ruled out because there are no features of pharyngitis, and this would not address the key differential of malaria in a returning traveller with fever.', 4),
('cb000000-0000-0000-0000-000000000041', 'E', 'Urine dipstick alone', false, 'Ruled out because urine dipstick alone would not diagnose or exclude malaria, which is the critical diagnosis to consider first in this clinical context.', 5),
('cb000000-0000-0000-0000-000000000042', 'A', 'Treat with oral antimalarials as an outpatient', false, 'Ruled out because features of severe malaria (confusion, jaundice, hypotension, high parasitaemia) require inpatient IV treatment, not outpatient oral therapy.', 1),
('cb000000-0000-0000-0000-000000000042', 'B', 'Discharge home with GP follow-up in one week', false, 'Ruled out because severe falciparum malaria is a life-threatening emergency requiring immediate hospital admission and treatment, not discharge.', 2),
('cb000000-0000-0000-0000-000000000042', 'C', 'Wait for a repeat blood film before starting any treatment', false, 'Ruled out because with a confirmed diagnosis and features of severe disease, treatment must be started immediately without delaying for repeat testing.', 3),
('cb000000-0000-0000-0000-000000000042', 'D', 'Treat with oral chloroquine', false, 'Ruled out because P. falciparum has widespread chloroquine resistance, and in any case oral therapy is inadequate for severe malaria, which requires IV artesunate.', 4),
('cb000000-0000-0000-0000-000000000042', 'E', 'Admit for treatment with IV artesunate as severe/complicated falciparum malaria', true, 'Correct. Confusion, jaundice, hypotension and a parasitaemia above 2% in P. falciparum infection indicate severe malaria, a medical emergency requiring admission (often to a high-dependency or intensive care setting) and treatment with IV artesunate.', 5),
('cb000000-0000-0000-0000-000000000043', 'A', 'Mosquito avoidance measures alone are sufficient, without medication', false, 'Ruled out because bite avoidance measures reduce but do not eliminate risk; chemoprophylaxis is also required for travel to malaria-endemic areas.', 1),
('cb000000-0000-0000-0000-000000000043', 'B', 'Take appropriate chemoprophylaxis for the specific region, in addition to mosquito bite avoidance measures (bed nets, insect repellent, covering exposed skin)', true, $x$Correct. Malaria prevention relies on a combination of chemoprophylaxis appropriate to the destination's resistance patterns and mosquito bite avoidance measures; neither alone is considered fully protective.$x$, 2),
('cb000000-0000-0000-0000-000000000043', 'C', 'Chemoprophylaxis is not needed if the stay is less than one week', false, 'Ruled out because malaria risk exists even with short stays in endemic areas, and chemoprophylaxis is recommended regardless of trip duration when travelling to at-risk regions.', 3),
('cb000000-0000-0000-0000-000000000043', 'D', 'Chemoprophylaxis is only needed if travelling during the rainy season', false, 'Ruled out because although mosquito density may vary seasonally, chemoprophylaxis is generally recommended for travel to endemic areas throughout the year, not only in specific seasons.', 4),
('cb000000-0000-0000-0000-000000000043', 'E', 'A vaccine alone provides full protection against malaria and no other precautions are needed', false, 'Ruled out because for the vast majority of travellers, routine malaria prevention still relies on chemoprophylaxis and bite avoidance rather than a stand-alone vaccine strategy.', 5),
('cb000000-0000-0000-0000-000000000044', 'A', 'Malaria', false, 'Ruled out because malaria typically causes cyclical fevers with rigors rather than the stepwise rising fever, relative bradycardia and rose spots described, which are more specific for typhoid.', 1),
('cb000000-0000-0000-0000-000000000044', 'B', 'Dengue fever', false, 'Ruled out because dengue typically presents with high fever, severe myalgia/retro-orbital headache and thrombocytopenia, rather than the stepwise fever pattern with relative bradycardia and rose spots seen here.', 2),
('cb000000-0000-0000-0000-000000000044', 'C', 'Viral hepatitis', false, 'Ruled out because viral hepatitis typically presents with jaundice, right upper quadrant discomfort and deranged liver function, rather than this specific fever pattern with rose spots.', 3),
('cb000000-0000-0000-0000-000000000044', 'D', 'Typhoid fever (Salmonella typhi infection)', true, 'Correct. A stepwise rising fever, relative bradycardia (a pulse-temperature dissociation), abdominal discomfort and rose spots on the trunk in a traveller returning from an endemic area (such as India) without prior vaccination is classic for typhoid fever.', 4),
('cb000000-0000-0000-0000-000000000044', 'E', 'Amoebic dysentery', false, 'Ruled out because amoebic dysentery classically presents with bloody diarrhoea rather than this systemic febrile illness with rose spots and relative bradycardia.', 5),
('cb000000-0000-0000-0000-000000000045', 'A', 'Oral rehydration therapy, with reassurance that this is likely to be self-limiting and antibiotics are not routinely required', true, $x$Correct. Uncomplicated traveller's diarrhoea without blood, high fever or systemic upset is usually self-limiting and managed with oral rehydration; routine antibiotic treatment is not required in mild, uncomplicated cases.$x$, 1),
('cb000000-0000-0000-0000-000000000045', 'B', 'Immediate IV antibiotics', false, 'Ruled out because there is no indication for antibiotics, let alone IV antibiotics, in mild uncomplicated watery diarrhoea without red flag features.', 2),
('cb000000-0000-0000-0000-000000000045', 'C', 'Hospital admission for observation', false, $x$Ruled out because mild traveller's diarrhoea without red flag features (blood, high fever, dehydration, systemic illness) does not require hospital admission and can be managed with simple measures.$x$, 3),
('cb000000-0000-0000-0000-000000000045', 'D', 'Strict fasting for 48 hours with no oral intake', false, 'Ruled out because prolonged strict fasting is not recommended; maintaining hydration with oral rehydration solution and tolerating light diet as able is the appropriate approach.', 4),
('cb000000-0000-0000-0000-000000000045', 'E', 'Anti-motility agents alone, without any rehydration measures', false, 'Ruled out because rehydration is the mainstay of management; anti-motility agents may occasionally be used for symptomatic relief in the absence of red flags, but should not replace rehydration as the primary treatment.', 5),
('cb000000-0000-0000-0000-000000000046', 'A', 'Malaria', false, 'Ruled out because malaria typically causes cyclical fevers with rigors rather than the combination of severe retro-orbital headache, rash and marked thrombocytopenia with bleeding tendency described here, which is more typical of dengue.', 1),
('cb000000-0000-0000-0000-000000000046', 'B', 'Typhoid fever', false, 'Ruled out because typhoid classically presents with stepwise fever, relative bradycardia and rose spots, rather than severe retro-orbital headache with marked thrombocytopenia and bleeding, which are more typical of dengue.', 2),
('cb000000-0000-0000-0000-000000000046', 'C', 'Chikungunya', false, 'Ruled out because although chikungunya can present with fever and severe joint pains, the combination of retro-orbital headache, marked thrombocytopenia and mucosal bleeding is more classic for dengue.', 3),
('cb000000-0000-0000-0000-000000000046', 'D', 'Leptospirosis', false, 'Ruled out because leptospirosis typically follows exposure to contaminated fresh water and often features conjunctival suffusion and renal/hepatic involvement, rather than this classic dengue symptom complex.', 4),
('cb000000-0000-0000-0000-000000000046', 'E', 'Dengue fever', true, $x$Correct. High fever, severe retro-orbital headache, myalgia/arthralgia ('breakbone fever'), a maculopapular rash, and thrombocytopenia with mild bleeding are classic features of dengue fever, common in returning travellers from South-East Asia.$x$, 5),
('cb000000-0000-0000-0000-000000000047', 'A', 'Isolate the patient immediately and contact infection control/public health for urgent risk assessment, avoiding unnecessary contact or invasive investigations until viral haemorrhagic fever is excluded', true, 'Correct. A fever with bleeding tendency in a traveller returning from an area with an active Ebola outbreak within the incubation period must be treated as a possible viral haemorrhagic fever; the patient should be isolated immediately, contact minimised, and infection control/public health notified urgently to guide safe assessment and testing, given the risk of transmission to staff and other patients.', 1),
('cb000000-0000-0000-0000-000000000047', 'B', 'Admit to a routine open ward without isolation while investigations are arranged', false, 'Ruled out because viral haemorrhagic fever carries a significant risk of transmission via body fluids; managing the patient on an open ward without isolation risks exposing staff and other patients.', 2),
('cb000000-0000-0000-0000-000000000047', 'C', 'Perform an immediate lumbar puncture to investigate the bleeding tendency', false, 'Ruled out because invasive procedures should be avoided until viral haemorrhagic fever has been excluded, both because of bleeding risk and the risk of exposure to staff performing the procedure.', 3),
('cb000000-0000-0000-0000-000000000047', 'D', 'Discharge home with outpatient follow-up given he is currently stable', false, 'Ruled out because this presentation requires urgent isolation and specialist assessment; discharging a patient with a possible viral haemorrhagic fever would risk community transmission and delay urgent care.', 4),
('cb000000-0000-0000-0000-000000000047', 'E', 'Give regular NSAIDs for symptomatic fever control', false, 'Ruled out because NSAIDs increase bleeding risk and should be avoided in a patient with a possible haemorrhagic fever; more fundamentally, the immediate priority is isolation and urgent specialist notification, not symptomatic treatment.', 5),
('cb000000-0000-0000-0000-000000000048', 'A', 'Simple urinary tract infection', false, $x$Ruled out because a straightforward bacterial UTI would not typically be associated with eosinophilia or a preceding freshwater exposure history with swimmer's itch.$x$, 1),
('cb000000-0000-0000-0000-000000000048', 'B', 'Schistosomiasis', true, $x$Correct. Freshwater exposure in an endemic area (such as Lake Malawi), a transient itchy rash at the time of exposure ('swimmer's itch'), and later haematuria with eosinophilia are classic for schistosomiasis, caused by Schistosoma species acquired through contact with contaminated freshwater.$x$, 2),
('cb000000-0000-0000-0000-000000000048', 'C', 'Renal calculus', false, 'Ruled out because a renal stone would not explain the eosinophilia or the preceding freshwater exposure and itchy rash, which point specifically towards a parasitic cause.', 3),
('cb000000-0000-0000-0000-000000000048', 'D', 'Bladder malignancy', false, $x$Ruled out as the most likely explanation because although chronic schistosomiasis is a recognised risk factor for bladder cancer in the longer term, this acute presentation with recent freshwater exposure, swimmer's itch and eosinophilia points to active schistosomiasis rather than malignancy.$x$, 4),
('cb000000-0000-0000-0000-000000000048', 'E', 'Malaria', false, $x$Ruled out because malaria does not typically cause haematuria or the swimmer's itch rash, and the exposure history (freshwater swimming) points specifically towards schistosomiasis.$x$, 5),
('cb000000-0000-0000-0000-000000000049', 'A', 'Close the wound with sutures and take no further action', false, 'Ruled out because simple wound closure without addressing the rabies exposure risk would leave the patient unprotected against a near-uniformly fatal infection if rabies transmission occurred.', 1),
('cb000000-0000-0000-0000-000000000049', 'B', 'Observe only, with no treatment given', false, 'Ruled out because observation alone is inadequate when the animal itself cannot be observed or tested; post-exposure prophylaxis should be started promptly.', 2),
('cb000000-0000-0000-0000-000000000049', 'C', 'Thoroughly wash the wound with soap and water, then give rabies post-exposure prophylaxis (vaccine, with rabies immunoglobulin if indicated)', true, 'Correct. Any bite from a mammal in a rabies-endemic area where the animal cannot be safely observed should be treated as a potential rabies exposure; thorough wound washing plus prompt post-exposure prophylaxis (vaccine +/- immunoglobulin depending on prior vaccination status and wound severity) is essential, as rabies is almost universally fatal once symptomatic.', 3),
('cb000000-0000-0000-0000-000000000049', 'D', 'Give antibiotics alone, without any rabies-specific treatment', false, 'Ruled out because antibiotics address bacterial wound infection risk but do not protect against rabies transmission, which requires specific post-exposure prophylaxis.', 4),
('cb000000-0000-0000-0000-000000000049', 'E', 'Delay any treatment for 10 days to see if the dog develops symptoms, since the dog cannot be located or observed', false, 'Ruled out because this option describes an observation strategy only valid when the animal can be reliably monitored; since the dog has run away and cannot be observed, post-exposure prophylaxis should be started without delay.', 5),
('cb000000-0000-0000-0000-000000000050', 'A', 'Hepatitis B vaccination covers this risk adequately', false, 'Ruled out because hepatitis B is transmitted via blood and body fluids (including sexual contact), not the faecal-oral route, and does not protect against hepatitis A.', 1),
('cb000000-0000-0000-0000-000000000050', 'B', 'No vaccination is available or needed for this risk', false, 'Ruled out because an effective and widely recommended hepatitis A vaccine is available and specifically indicated for travellers to endemic areas.', 2),
('cb000000-0000-0000-0000-000000000050', 'C', 'Prophylactic antibiotics prevent this infection', false, 'Ruled out because hepatitis A is a viral infection; antibiotics have no role in its prevention.', 3),
('cb000000-0000-0000-0000-000000000050', 'D', 'Hepatitis A vaccination prior to travel', true, 'Correct. Hepatitis A is transmitted via the faecal-oral route and is common in areas with poor sanitation; pre-travel vaccination is the most effective way to reduce this specific risk for travellers to endemic regions such as rural India.', 4),
('cb000000-0000-0000-0000-000000000050', 'E', 'Food and water hygiene precautions alone are sufficient, and vaccination is not recommended', false, 'Ruled out because although food and water hygiene reduce risk, vaccination is specifically recommended in addition to hygiene measures for travellers to endemic areas, given the seriousness and continued risk of exposure.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('cb000000-0000-0000-0000-000000000001', 'A history of rash plus facial/lip swelling after a penicillin suggests a true IgE-mediated allergy, and all penicillins (including co-amoxiclav and piperacillin-tazobactam) should be avoided.', 1),
('cb000000-0000-0000-0000-000000000001', 'Macrolides (clarithromycin) or tetracyclines (doxycycline) are standard alternatives for streptococcal/staphylococcal skin infections in penicillin-allergic patients.', 2),
('cb000000-0000-0000-0000-000000000002', 'Broad-spectrum antibiotics (co-amoxiclav, cephalosporins, clindamycin, fluoroquinolones) are classic precipitants of C. difficile infection and should be stopped where possible.', 1),
('cb000000-0000-0000-0000-000000000002', 'Oral vancomycin (or fidaxomicin) is first-line treatment; IV vancomycin and IV metronidazole do not work because they fail to reach adequate luminal gut concentrations.', 2),
('cb000000-0000-0000-0000-000000000002', 'Anti-motility agents such as loperamide should be avoided as they risk precipitating toxic megacolon.', 3),
('cb000000-0000-0000-0000-000000000003', 'Aminoglycosides (gentamicin) cause dose-dependent nephrotoxicity and ototoxicity; new tinnitus or rising creatinine should prompt immediate review and level monitoring.', 1),
('cb000000-0000-0000-0000-000000000003', 'Aminoglycoside levels (peak/trough or once-daily nomogram levels) must be monitored throughout treatment, especially with any evidence of toxicity or renal impairment.', 2),
('cb000000-0000-0000-0000-000000000004', 'CURB-65 (Confusion, Urea >7 mmol/L, Respiratory rate >=30, low Blood pressure, age >=65) stratifies pneumonia severity and guides antibiotic choice and site of care.', 1),
('cb000000-0000-0000-0000-000000000004', 'Severe CAP requires prompt IV broad-spectrum combination therapy (beta-lactam plus macrolide) to cover both typical and atypical pathogens; antibiotics should never be delayed pending cultures.', 2),
('cb000000-0000-0000-0000-000000000005', 'Red man syndrome is a rate-related, non-allergic histamine release reaction to vancomycin, causing flushing/itching without haemodynamic or airway compromise.', 1),
('cb000000-0000-0000-0000-000000000005', 'Management is to slow the infusion rate (and consider antihistamine premedication), not to label the patient allergic or stop the drug permanently.', 2),
('cb000000-0000-0000-0000-000000000006', 'Metronidazole causes a disulfiram-like reaction with alcohol via inhibition of aldehyde dehydrogenase; patients must be advised to avoid alcohol during and for 48 hours after treatment.', 1),
('cb000000-0000-0000-0000-000000000006', 'Distinguishing antibiotic-specific adverse effects (aminoglycoside oto/nephrotoxicity, fluoroquinolone tendinopathy, vancomycin red man syndrome, metronidazole-alcohol reaction) is a common safe-prescribing theme.', 2),
('cb000000-0000-0000-0000-000000000007', 'Necrotising fasciitis should be suspected with pain disproportionate to visible signs, rapidly spreading erythema, crepitus, bullae, or systemic toxicity, especially in diabetic or immunocompromised patients.', 1),
('cb000000-0000-0000-0000-000000000007', 'Management is urgent surgical debridement plus broad-spectrum IV antibiotics and resuscitation; imaging or antibiotics alone must never delay surgical referral.', 2),
('cb000000-0000-0000-0000-000000000008', 'Nitrofurantoin should be avoided in the third trimester/near term due to a theoretical risk of neonatal haemolysis.', 1),
('cb000000-0000-0000-0000-000000000008', 'Trimethoprim should be avoided in the first trimester due to its folate-antagonist, teratogenic potential (risk of neural tube defects).', 2),
('cb000000-0000-0000-0000-000000000009', $x$Trimethoprim's folate-antagonist action makes it best avoided in the first trimester of pregnancy due to teratogenic risk; nitrofurantoin is generally preferred in early pregnancy instead.$x$, 1),
('cb000000-0000-0000-0000-000000000009', 'Different antibiotics carry different trimester-specific risks in pregnancy: trimethoprim (first trimester, folate antagonism), nitrofurantoin (third trimester, neonatal haemolysis), tetracyclines (all trimesters, fetal bone/teeth), and fluoroquinolones (generally avoided, joint/cartilage concerns).', 2),
('cb000000-0000-0000-0000-000000000010', 'Tetracyclines (including doxycycline) are generally avoided in children under 12 and in pregnancy due to permanent tooth discolouration and effects on developing bone.', 1),
('cb000000-0000-0000-0000-000000000010', 'Recognising age- and pregnancy-specific antibiotic contraindications is a key UKMLA safe-prescribing theme.', 2),
('cb000000-0000-0000-0000-000000000011', 'HIV PEP is most effective when started within hours of exposure and should not be delayed beyond 72 hours; occupational health or the emergency department should be contacted immediately.', 1),
('cb000000-0000-0000-0000-000000000011', 'Needlestick injuries should also prompt assessment of hepatitis B and C risk, but this does not replace or delay urgent PEP consideration for HIV.', 2),
('cb000000-0000-0000-0000-000000000012', 'Recurrent oral/oesophageal candidiasis, unexplained weight loss, night sweats, and seborrhoeic dermatitis are HIV indicator conditions that should prompt an offer of testing.', 1),
('cb000000-0000-0000-0000-000000000012', 'HIV testing should be offered proactively in indicator presentations even without disclosed risk factors, as many patients with HIV have no recognised risk factor elicited on history.', 2),
('cb000000-0000-0000-0000-000000000013', 'PCP classically presents in advanced HIV (CD4 <200) with subacute dyspnoea, dry cough, and exertional desaturation, with bilateral perihilar interstitial infiltrates on chest X-ray.', 1),
('cb000000-0000-0000-0000-000000000013', 'TB remains an important differential in HIV and should always be actively considered and excluded, but the exertional desaturation pattern here is more typical of PCP.', 2),
('cb000000-0000-0000-0000-000000000014', 'High-dose co-trimoxazole is first-line treatment for PCP in HIV; adjunctive corticosteroids are indicated when there is significant hypoxia (typically PaO2 <9.3 kPa or similar thresholds).', 1),
('cb000000-0000-0000-0000-000000000014', 'Co-trimoxazole is also used as prophylaxis against PCP in patients with CD4 counts below 200 cells/microL.', 2),
('cb000000-0000-0000-0000-000000000015', 'Multiple ring-enhancing brain lesions at the grey-white junction/basal ganglia in a patient with CD4 <100 is classic for cerebral toxoplasmosis, the most common HIV-associated CNS mass lesion.', 1),
('cb000000-0000-0000-0000-000000000015', 'Primary CNS lymphoma is the key differential (typically a single lesion) and PML causes non-enhancing white matter change without mass effect; distinguishing these patterns is an important, more advanced diagnostic skill.', 2),
('cb000000-0000-0000-0000-000000000016', 'Fourth-generation combined antigen/antibody tests shorten the window period compared with antibody-only tests, but a repeat test at 12 weeks post-exposure is still recommended to fully exclude infection.', 1),
('cb000000-0000-0000-0000-000000000016', 'Patient anxiety about early false-negative results should be addressed by explaining the window period concept and arranging appropriate repeat testing.', 2),
('cb000000-0000-0000-0000-000000000017', $x$Current guidance recommends starting ART in all patients diagnosed with HIV as soon as possible, regardless of CD4 count or symptoms ('treat all').$x$, 1),
('cb000000-0000-0000-0000-000000000017', 'Early ART initiation reduces the risk of onward transmission and long-term immune damage, representing a shift from older CD4-threshold-based approaches.', 2),
('cb000000-0000-0000-0000-000000000018', 'Cryptococcal meningitis occurs in advanced HIV (CD4 <100) with a subacute headache, fever, and raised intracranial pressure; India ink staining or cryptococcal antigen testing confirms the diagnosis.', 1),
('cb000000-0000-0000-0000-000000000018', 'Raised CSF opening pressure is a key feature of cryptococcal meningitis and may itself need active management (e.g., therapeutic lumbar puncture) alongside antifungal treatment.', 2),
('cb000000-0000-0000-0000-000000000019', 'TB is more common in HIV co-infection and often presents atypically, particularly at lower CD4 counts, without the classic cavitating upper-lobe changes seen in immunocompetent patients.', 1),
('cb000000-0000-0000-0000-000000000019', 'Any HIV-positive patient with chronic cough, weight loss and night sweats should have TB actively investigated with sputum AFB smear, culture and NAAT, regardless of chest X-ray appearance.', 2),
('cb000000-0000-0000-0000-000000000020', 'PEPSE should be started as soon as possible after high-risk sexual exposure and is not effective if started after 72 hours.', 1),
('cb000000-0000-0000-0000-000000000020', $x$PEP decisions are based on risk assessment of the exposure itself, not on waiting for confirmation of the source's HIV status, as this would cause harmful delay.$x$, 2),
('cb000000-0000-0000-0000-000000000021', 'Pre-operative MRSA-positive patients should undergo topical decolonisation (nasal mupirocin, chlorhexidine body wash) before elective surgery to reduce surgical site infection risk.', 1),
('cb000000-0000-0000-0000-000000000021', 'MRSA colonisation is treated with topical decolonisation, not systemic antibiotics, as it is resistant to agents such as flucloxacillin.', 2),
('cb000000-0000-0000-0000-000000000022', 'C. difficile spores are resistant to alcohol gel; hand hygiene must be performed with soap and water for effective mechanical removal.', 1),
('cb000000-0000-0000-0000-000000000022', 'Patients with C. difficile infection require single-room isolation and contact precautions (gloves and apron) to prevent onward transmission.', 2),
('cb000000-0000-0000-0000-000000000023', 'Urinary catheters should only be inserted for clear clinical indications and removed as soon as they are no longer needed to reduce catheter-associated UTI risk.', 1),
('cb000000-0000-0000-0000-000000000023', 'Asymptomatic bacteriuria (including cloudy urine or a positive culture without symptoms) does not require antibiotic treatment in most patients.', 2),
('cb000000-0000-0000-0000-000000000024', 'Surgical antibiotic prophylaxis should be given within 60 minutes before skin incision to maximise tissue concentration during the period of contamination risk.', 1),
('cb000000-0000-0000-0000-000000000024', 'Prophylaxis is typically a single dose (or short course), not a prolonged post-operative course, unless there is an established infection requiring treatment.', 2),
('cb000000-0000-0000-0000-000000000025', 'CLABSI is diagnosed using criteria such as growth of the same organism from the line and peripheral blood, often with the line sample becoming positive earlier (differential time to positivity).', 1),
('cb000000-0000-0000-0000-000000000025', 'Coagulase-negative staphylococci are common skin commensals but are also a leading cause of true line-related bacteraemia given prolonged central venous access.', 2),
('cb000000-0000-0000-0000-000000000026', 'A sudden cluster of vomiting and diarrhoea among patients and staff on a ward is typical of a norovirus outbreak, requiring ward closure to new admissions and isolation/cohorting of cases.', 1),
('cb000000-0000-0000-0000-000000000026', 'Isolation should continue until patients have been symptom-free for at least 48 hours to reduce ongoing environmental and person-to-person spread.', 2),
('cb000000-0000-0000-0000-000000000027', 'First aid for sharps injuries: wash with soap and water, encourage bleeding, do not suck the wound, then report immediately to occupational health/the relevant local protocol.', 1),
('cb000000-0000-0000-0000-000000000027', 'Prompt reporting is essential because risk assessment and any indicated post-exposure prophylaxis are most effective the sooner they are started.', 2),
('cb000000-0000-0000-0000-000000000028', 'Asymptomatic colonisation with multidrug-resistant organisms such as VRE does not require antibiotic treatment, but does require contact precautions to prevent transmission.', 1),
('cb000000-0000-0000-0000-000000000028', 'Treating colonisation rather than true infection with antibiotics contributes to further resistance selection without clinical benefit.', 2),
('cb000000-0000-0000-0000-000000000029', $x$The WHO's five moments for hand hygiene are: before touching a patient, before a clean/aseptic procedure, after body fluid exposure risk, after touching a patient, and after touching patient surroundings.$x$, 1),
('cb000000-0000-0000-0000-000000000029', 'Hand hygiene compliance at all five moments, not just visibly obvious ones, is essential to reducing healthcare-associated infection transmission.', 2),
('cb000000-0000-0000-0000-000000000030', 'Suspected or confirmed smear-positive pulmonary TB requires airborne precautions, ideally in a negative pressure single room, due to transmission via infectious droplet nuclei.', 1),
('cb000000-0000-0000-0000-000000000030', 'Isolation should be instituted as soon as TB is clinically suspected, without waiting for full microbiological confirmation, given the potential for onward transmission.', 2),
('cb000000-0000-0000-0000-000000000031', 'The Sepsis Six (blood cultures, lactate, urine output, oxygen, IV fluids, IV antibiotics) should be delivered within one hour of recognising sepsis.', 1),
('cb000000-0000-0000-0000-000000000031', 'Investigations to identify the source (e.g., imaging) should not delay the immediate Sepsis Six bundle in a haemodynamically compromised, septic patient.', 2),
('cb000000-0000-0000-0000-000000000032', 'NEWS2 is the standard UK track-and-trigger early warning score used to detect clinical deterioration, including evolving sepsis, on general wards.', 1),
('cb000000-0000-0000-0000-000000000032', 'Recognising which scoring tool applies to which clinical scenario (NEWS2 for deterioration, CURB-65 for pneumonia severity, Wells for VTE, Glasgow-Blatchford for GI bleeding) is a common safe-practice theme.', 2),
('cb000000-0000-0000-0000-000000000033', 'Fluid-refractory septic shock (persistent hypotension despite 30 mL/kg fluid) requires vasopressor support (typically noradrenaline) and urgent critical care referral.', 1),
('cb000000-0000-0000-0000-000000000033', 'Rising lactate despite resuscitation indicates ongoing tissue hypoperfusion and should prompt escalation rather than further unmonitored fluid boluses alone.', 2),
('cb000000-0000-0000-0000-000000000034', 'Neutropenic sepsis (fever plus significant neutropenia, typically <0.5 x10^9/L, in a patient who has had recent chemotherapy) is a medical emergency requiring IV broad-spectrum antibiotics within one hour.', 1),
('cb000000-0000-0000-0000-000000000034', 'Antibiotics must never be delayed while awaiting blood count confirmation or culture results in suspected neutropenic sepsis.', 2),
('cb000000-0000-0000-0000-000000000035', 'Blood cultures should ideally be taken before the first dose of antibiotics, but this must never delay antibiotic administration beyond the one-hour target in sepsis.', 1),
('cb000000-0000-0000-0000-000000000035', 'The Sepsis Six emphasises simultaneous, rapid action (cultures, lactate, oxygen, fluids, antibiotics, urine output monitoring) rather than sequential delay.', 2),
('cb000000-0000-0000-0000-000000000036', 'Source control (e.g., drainage of an abscess, removal of an infected device) is essential in sepsis where there is an undrained collection, as antibiotics alone are often insufficient.', 1),
('cb000000-0000-0000-0000-000000000036', 'Ongoing systemic upset despite appropriate antibiotics should prompt urgent reassessment for a source requiring active intervention, rather than simply escalating antibiotic therapy.', 2),
('cb000000-0000-0000-0000-000000000037', 'Suspected infective endocarditis requires three sets of blood cultures from different sites before starting antibiotics, to maximise organism identification for guiding prolonged treatment.', 1),
('cb000000-0000-0000-0000-000000000037', 'Risk factors for endocarditis include prosthetic valves and intravenous drug use; clinical clues include new murmurs and peripheral stigmata such as splinter haemorrhages.', 2),
('cb000000-0000-0000-0000-000000000038', 'Suspected meningococcal sepsis (fever, non-blanching rash, meningism) requires immediate pre-hospital benzylpenicillin (if available and no contraindication) and urgent transfer to hospital.', 1),
('cb000000-0000-0000-0000-000000000038', 'A non-blanching rash in a febrile, unwell patient is a critical red flag that must never be managed with reassurance or delayed follow-up.', 2),
('cb000000-0000-0000-0000-000000000039', 'Serum lactate is a key marker of tissue hypoperfusion in sepsis; a persistently elevated or rising lactate despite initial treatment indicates inadequate resuscitation and the need for escalation.', 1),
('cb000000-0000-0000-0000-000000000039', 'Lactate should be remeasured after initial resuscitation to assess response to treatment, guiding further fluid, vasopressor, or critical care decisions.', 2),
('cb000000-0000-0000-0000-000000000040', 'Elderly and frail patients often present with sepsis atypically, without significant fever; new confusion, tachycardia or reduced oral intake should still raise suspicion of infection.', 1),
('cb000000-0000-0000-0000-000000000040', 'A normal or low temperature should never be used in isolation to exclude sepsis, particularly in older patients.', 2),
('cb000000-0000-0000-0000-000000000041', 'Any fever in a returning traveller from a malaria-endemic area must prompt urgent thick and thin blood films (or rapid diagnostic testing) to exclude malaria.', 1),
('cb000000-0000-0000-0000-000000000041', 'A single negative blood film does not fully exclude malaria; repeat films over 24-48 hours may be needed if clinical suspicion remains high.', 2),
('cb000000-0000-0000-0000-000000000042', 'Severe/complicated falciparum malaria (defined by features such as impaired consciousness, jaundice, hypotension, renal impairment, or parasitaemia >2%) requires urgent admission and IV artesunate.', 1),
('cb000000-0000-0000-0000-000000000042', 'Chloroquine is not appropriate for P. falciparum due to widespread resistance, and oral therapy is inadequate once severity criteria are met.', 2),
('cb000000-0000-0000-0000-000000000043', 'Effective malaria prevention combines destination-appropriate chemoprophylaxis with mosquito bite avoidance measures; neither is sufficient alone.', 1),
('cb000000-0000-0000-0000-000000000043', 'Malaria risk applies to short as well as long stays in endemic regions, and prophylaxis recommendations are not limited to a particular season.', 2),
('cb000000-0000-0000-0000-000000000044', 'Typhoid fever classically presents with a stepwise rising fever, relative bradycardia, abdominal symptoms, and rose spots in travellers returning from endemic areas (South Asia, parts of Africa).', 1),
('cb000000-0000-0000-0000-000000000044', 'Pre-travel typhoid vaccination reduces but does not completely eliminate risk; unvaccinated travellers to endemic regions remain at meaningful risk.', 2),
('cb000000-0000-0000-0000-000000000045', $x$Uncomplicated traveller's diarrhoea (no blood, no high fever, no systemic upset) is usually self-limiting and managed with oral rehydration; antibiotics are not routinely required.$x$, 1),
('cb000000-0000-0000-0000-000000000045', 'Red flag features (bloody diarrhoea, high fever, signs of dehydration or systemic illness) should prompt further assessment and consideration of investigation or treatment beyond simple rehydration.', 2),
('cb000000-0000-0000-0000-000000000046', 'Dengue fever presents with high fever, severe retro-orbital headache, myalgia/arthralgia, rash, and thrombocytopenia, sometimes with bleeding tendency in more severe cases.', 1),
('cb000000-0000-0000-0000-000000000046', 'Aspirin and NSAIDs should be avoided in suspected dengue due to the bleeding risk associated with thrombocytopenia; paracetamol is preferred for symptomatic relief.', 2),
('cb000000-0000-0000-0000-000000000047', 'Fever with bleeding tendency in a traveller returning from an area with an active viral haemorrhagic fever outbreak, within the incubation period, requires immediate isolation and urgent public health/infection control notification.', 1),
('cb000000-0000-0000-0000-000000000047', 'Invasive procedures and unnecessary patient contact should be minimised until viral haemorrhagic fever has been excluded, given the risk of transmission via body fluids.', 2),
('cb000000-0000-0000-0000-000000000047', 'This scenario represents a rare but safety-critical presentation requiring recognition of when standard assessment pathways must be deliberately deviated from to protect staff and other patients.', 3),
('cb000000-0000-0000-0000-000000000048', $x$Schistosomiasis should be considered in travellers with freshwater exposure in endemic areas, a history of swimmer's itch, and later haematuria (S. haematobium) or gastrointestinal symptoms (S. mansoni), often with eosinophilia.$x$, 1),
('cb000000-0000-0000-0000-000000000048', 'Chronic schistosomiasis is a recognised long-term risk factor for bladder cancer, but this should be distinguished from the acute presentation with recent exposure described here.', 2),
('cb000000-0000-0000-0000-000000000049', 'Any mammal bite in a rabies-endemic area, where the animal cannot be reliably observed, warrants thorough wound washing plus prompt rabies post-exposure prophylaxis.', 1),
('cb000000-0000-0000-0000-000000000049', $x$Rabies is almost universally fatal once clinical symptoms develop, making timely post-exposure prophylaxis critical rather than a 'wait and see' approach when the animal cannot be monitored.$x$, 2),
('cb000000-0000-0000-0000-000000000050', 'Hepatitis A is transmitted via the faecal-oral route and is preventable with pre-travel vaccination, recommended for travellers to areas with poor sanitation.', 1),
('cb000000-0000-0000-0000-000000000050', 'Hepatitis A and hepatitis B differ in transmission route (faecal-oral versus blood-borne/sexual) and therefore require separate vaccines targeted at the relevant risk.', 2);
